WHERE artist_id = #{sourceId}
  AND song_id IN (
      SELECT song_id FROM song_artist WHERE artist_id = #{targetId}
  )

DELETE FROM song_artist
WHERE artist_id = #{sourceId}
  AND song_id IN (
      SELECT song_id FROM (SELECT sa.song_id AS song_id FROM song_artist sa WHERE sa.artist_id = #{targetId}) tmp
