where.if:
AND id IN (
    SELECT DISTINCT sa.artist_id FROM song_artist sa
    JOIN song_style ss ON sa.song_id = ss.song_id
    JOIN style st ON ss.style_id = st.id
    WHERE st.style_name = #{style}
)
